THOUGHT: The new request specifies a C++ implementation with polynomial degrees 1-3 and 5-fold CV, tuning the ridge alpha. Since alpha values were not explicitly listed, I'll keep the same grid as the original context: `[0.1, 1.0, 10.0]`. I'll implement ridge regression using normal equations with polynomial features, shuffle fold indices with seed 42 for reproducibility, compute mean CV MSE for all 9 combinations, save sorted results, retrain on the full train set, and write test predictions to 4 decimal places. No extra packages are needed since g++ is available.

```mswea_bash_command
mkdir -p /home/user/experiments && cat <<'EOF' > /home/user/experiments/ridge_cv.cpp
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <random>
#include <sstream>
#include <string>
#include <vector>

using Matrix = std::vector<std::vector<double>>;
using Vector = std::vector<double>;

struct DataPoint {
    double x;
    double y;
};

struct ResultRow {
    int degree;
    double alpha;
    double mse;
};

Vector solveLinear(Matrix A, Vector b) {
    int n = static_cast<int>(A.size());
    for (int col = 0; col < n; ++col) {
        int pivot = col;
        for (int i = col + 1; i < n; ++i) {
            if (std::fabs(A[i][col]) > std::fabs(A[pivot][col])) {
                pivot = i;
            }
        }
        if (pivot != col) {
            std::swap(A[pivot], A[col]);
            std::swap(b[pivot], b[col]);
        }
        double pv = A[col][col];
        for (int j = col; j < n; ++j) {
            A[col][j] /= pv;
        }
        b[col] /= pv;
        for (int i = 0; i < n; ++i) {
            if (i == col) continue;
            double factor = A[i][col];
            if (std::fabs(factor) < 1e-15) continue;
            for (int j = col; j < n; ++j) {
                A[i][j] -= factor * A[col][j];
            }
            b[i] -= factor * b[col];
        }
    }
    return b;
}

Vector ridgeFit(const std::vector<DataPoint>& data, int degree, double alpha) {
    int p = degree + 1;
    Matrix XtX(p, Vector(p, 0.0));
    Vector Xty(p, 0.0);

    for (const auto& pt : data) {
        Vector phi(p, 1.0);
        for (int k = 1; k <= degree; ++k) {
            phi[k] = phi[k - 1] * pt.x;
        }
        for (int i = 0; i < p; ++i) {
            Xty[i] += phi[i] * pt.y;
            for (int j = 0; j < p; ++j) {
                XtX[i][j] += phi[i] * phi[j];
            }
        }
    }

    for (int i = 0; i < p; ++i) {
        XtX[i][i] += alpha;
    }

    return solveLinear(XtX, Xty);
}

double predictOne(const Vector& beta, double x, int degree) {
    double result = 0.0;
    double xp = 1.0;
    for (int k = 0; k <= degree; ++k) {
        result += beta[k] * xp;
        xp *= x;
    }
    return result;
}

double foldMSE(const std::vector<DataPoint>& data, const std::vector<int>& idx,
               int start, int end, int degree, double alpha) {
    std::vector<DataPoint> train;
    std::vector<DataPoint> val;

    for (int pos = 0; pos < static_cast<int>(idx.size()); ++pos) {
        if (pos >= start && pos < end) {
            val.push_back(data[idx[pos]]);
        } else {
            train.push_back(data[idx[pos]]);
        }
    }

    Vector beta = ridgeFit(train, degree, alpha);
    double se = 0.0;
    for (const auto& v : val) {
        double err = predictOne(beta, v.x, degree) - v.y;
        se += err * err;
    }
    return se / static_cast<double>(val.size());
}

std::vector<DataPoint> loadTrain(const std::string& path) {
    std::ifstream in(path);
    std::vector<DataPoint> data;
    std::string line;
    std::getline(in, line); // skip header
    while (std::getline(in, line)) {
        std::replace(line.begin(), line.end(), ',', ' ');
        std::istringstream ss(line);
        double x, y;
        if (ss >> x >> y) {
            data.push_back({x, y});
        }
    }
    return data;
}

std::vector<double> loadTest(const std::string& path) {
    std::ifstream in(path);
    std::vector<double> xs;
    std::string line;
    std::getline(in, line); // skip header
    while (std::getline(in, line)) {
        double x;
        std::istringstream ss(line);
        if (ss >> x) {
            xs.push_back(x);
        }
    }
    return xs;
}

int main() {
    std::vector<DataPoint> train = loadTrain("/home/user/data/train.csv");
    std::vector<double> test = loadTest("/home/user/data/test.csv");

    int folds = 5;
    int n = static_cast<int>(train.size());

    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    std::mt19937 rng(42);
    std::shuffle(idx.begin(), idx.end(), rng);

    std::vector<int> degrees = {1, 2, 3};
    std::vector<double> alphas = {0.1, 1.0, 10.0};

    std::vector<ResultRow> results;

    for (int deg : degrees) {
        for (double alpha : alphas) {
            double sum = 0.0;
            for (int fold = 0; fold < folds; ++fold) {
                int start = fold * n / folds;
                int end = (fold + 1) * n / folds;
                sum += foldMSE(train, idx, start, end, deg, alpha);
            }
            results.push_back({deg, alpha, sum / folds});
        }
    }

    std::stable_sort(results.begin(), results.end(),
                     [](const ResultRow& a, const ResultRow& b) {
                         return a.mse < b.mse;
                     });

    std::ofstream cvOut("/home/user/experiments/cv_results.csv");
    cvOut << "degree,alpha,mean_mse\n";
    for (const auto& r : results) {
        cvOut << r.degree << ","
              << std::fixed << std::setprecision(4) << r.alpha << ","
              << std::fixed << std::setprecision(4) << r.mse << "\n";
    }
    cvOut.close();

    const ResultRow& best = results.front();
    Vector beta = ridgeFit(train, best.degree, best.alpha);

    std::ofstream predOut("/home/user/experiments/predictions.txt");
    predOut << std::fixed << std::setprecision(4);
    for (double x : test) {
        predOut << predictOne(beta, x, best.degree) << "\n";
    }
    predOut.close();

    std::cout << "Best hyperparameters: degree = " << best.degree
              << ", alpha = " << std::fixed << std::setprecision(4) << best.alpha << "\n";
    std::cout << "Best mean MSE = " << std::fixed << std::setprecision(4) << best.mse << "\n";
    std::cout << "CV results saved to /home/user/experiments/cv_results.csv\n";
    std::cout << "Predictions saved to /home/user/experiments/predictions.txt\n";

    return 0;
}
EOF
g++ -std=c++17 -O2 -o /home/user/experiments/ridge_cv /home/user/experiments/ridge_cv.cpp && /home/user/experiments/ridge_cv
```

