#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <random>
#include <sstream>
#include <string>
#include <vector>

using Matrix = std::vector<std::vector<double>>;
using Vector = std::vector<double>;

struct DataPoint { double x, y; };

Vector solveLinear(Matrix A, Vector b) {
    int n = A.size();
    for (int col=0; col<n; ++col) {
        int pivot = col;
        for (int i=col+1; i<n; ++i)
            if (std::fabs(A[i][col]) > std::fabs(A[pivot][col])) pivot=i;
        if (pivot != col) {
            std::swap(A[pivot], A[col]);
            std::swap(b[pivot], b[col]);
        }
        double pv = A[col][col];
        if (std::fabs(pv) < 1e-12) { // should not happen
            // handle fallback by adding small identity? Could ignore.
        }
        for (int j=col; j<n; ++j) A[col][j] /= pv;
        b[col] /= pv;
        for (int i=0; i<n; ++i) {
            if (i == col) continue;
            double factor = A[i][col];
            if (std::fabs(factor) < 1e-15) continue;
            for (int j=col; j<n; ++j) A[i][j] -= factor * A[col][j];
            b[i] -= factor * b[col];
        }
    }
    return b;
}

Vector ridgeFit(const std::vector<DataPoint>& train, int degree, double alpha) {
    int p = degree + 1;
    Matrix XtX(p, Vector(p, 0.0));
    Vector Xty(p, 0.0);
    for (const auto& pt : train) {
        Vector phi(p, 1.0);
        for (int k=1; k<=degree; ++k) phi[k] = phi[k-1] * pt.x;
        for (int i=0; i<p; ++i) {
            Xty[i] += phi[i] * pt.y;
            for (int j=0; j<p; ++j) XtX[i][j] += phi[i] * phi[j];
        }
    }
    for (int i=0;i<p;++i) XtX[i][i] += alpha; // includes intercept; can choose not add i=0
    return solveLinear(XtX, Xty);
}

double predictOne(const Vector& beta, double x, int degree) {
    double result = 0.0;
    double xp = 1.0;
    for (int k=0; k<=degree; ++k) {
        result += beta[k] * xp;
        xp *= x;
    }
    return result;
}

double foldMSE(const std::vector<DataPoint>& data, const std::vector<int>& idx, int start, int end, int degree, double alpha) {
    std::vector<DataPoint> train;
    std::vector<DataPoint> val;
    for (int pos=0; pos<(int)idx.size(); ++pos) {
        if (pos >= start && pos < end) val.push_back(data[idx[pos]]);
        else train.push_back(data[idx[pos]]);
    }
    Vector beta = ridgeFit(train, degree, alpha);
    double se=0;
    for (auto& v:val) { double err=predictOne(beta,v.x,degree)-v.y; se += err*err; }
    return se / val.size();
}

